const PROJECT_IDS = new Set(NODES.map((x) => x.id));
const LANDSCAPE_IDS = new Set(RH_LANDSCAPE_DAG.nodes.map((x) => x.id));
const resolve = (id) => PROJECT_DAG_ALIAS[id] || id;

// Alias-resolved, self-loop-free, deduplicated on (from, to): the first listing wins.
const EDGES = (() => {
  const seen = new Set();
  const out = [];
  for (const [f, t, type, note] of RAW_EDGES) {
    const from = resolve(f);
    const to = resolve(t);
    if (from === to) continue;
    const key = `${from}|${to}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(Object.freeze({ from, to, type, ...(note ? { note } : {}),
      ...(LANDSCAPE_IDS.has(to) || LANDSCAPE_IDS.has(from) ? { landscape: true } : {}) }));
  }
  return out;
})();

